// ============================================================
// PANGI ORCHESTRATOR — Message Extractor v1.0.0
// Compatible con Evolution API V2 webhook payload.
// ============================================================

const body = $input.first().json.body || $input.first().json;
const event = body.event;
const instance = body.instance || 'Test1';
const data = body.data;

// Solo procesamos mensajes reales
if (event !== 'messages.upsert') {
  return [{ json: { valid: false, reason: 'not_message_event', event } }];
}
if (!data) {
  return [{ json: { valid: false, reason: 'no_data_field' } }];
}

const key          = data.key || {};
// Evolution API V2 puede enviar remoteJid en formato @lid (nuevo formato WhatsApp).
// remoteJidAlt contiene el JID tradicional @s.whatsapp.net que Evolution puede usar.
// Priorizamos el formato tradicional para compatibilidad con sendText.
const remoteJid = key.remoteJidAlt || key.remoteJid || '';
const fromMe       = key.fromMe   || false;
const messageId    = key.id       || '';
const pushName     = data.pushName || null;
const timestamp    = data.messageTimestamp || Math.floor(Date.now() / 1000);

// ── FILTROS ───────────────────────────────────────────────
// Ignorar mensajes propios (enviados por el bot)
if (fromMe)  return [{ json: { valid: false, reason: 'from_me', remoteJid } }];
// Ignorar grupos
if (remoteJid.endsWith('@g.us')) return [{ json: { valid: false, reason: 'group_message' } }];
// Ignorar estados de WhatsApp
if (remoteJid === 'status@broadcast') return [{ json: { valid: false, reason: 'status_broadcast' } }];
// Ignorar mensajes vacíos de notificación
if (!remoteJid) return [{ json: { valid: false, reason: 'no_remote_jid' } }];

// ── LIMPIAR NÚMERO DE TELÉFONO ─────────────────────────────
const phone = '+' + remoteJid
  .replace('@s.whatsapp.net','')
  .replace('@c.us','')
  .replace('@lid','')
  .replace(/@[^@]+$/,''); // catch-all para cualquier sufijo futuro

// ── EXTRAER CONTENIDO DEL MENSAJE ─────────────────────────
const msg = data.message || {};
let messageText = '';
let messageType = 'unknown';

if (msg.conversation) {
  messageText = msg.conversation;
  messageType = 'text';
} else if (msg.extendedTextMessage?.text) {
  messageText = msg.extendedTextMessage.text;
  messageType = 'text';
} else if (msg.buttonsResponseMessage?.selectedButtonId) {
  // Respuesta de botón clásico
  messageText = msg.buttonsResponseMessage.selectedButtonId;
  messageType = 'button_reply';
} else if (msg.listResponseMessage?.singleSelectReply?.selectedRowId) {
  // Respuesta de lista
  messageText = msg.listResponseMessage.singleSelectReply.selectedRowId;
  messageType = 'button_reply';
} else if (msg.interactiveResponseMessage?.nativeFlowResponseMessage) {
  // Respuesta interactiva (botones nativos WhatsApp)
  try {
    const params = JSON.parse(msg.interactiveResponseMessage.nativeFlowResponseMessage.paramsJson || '{}');
    messageText = params.id || params.title || '';
    messageType = 'button_reply';
  } catch(e) { messageText = ''; messageType = 'button_reply'; }
} else if (msg.imageMessage) {
  messageText = msg.imageMessage.caption || '[Imagen recibida]';
  messageType = 'image';
} else if (msg.audioMessage || msg.pttMessage) {
  messageText = '[Audio recibido — función de voz próximamente]';
  messageType = 'audio';
} else if (msg.documentMessage) {
  messageText = `[Documento recibido: ${msg.documentMessage.fileName || 'archivo'}]`;
  messageType = 'document';
} else if (msg.stickerMessage) {
  messageText = '[Sticker]';
  messageType = 'sticker';
}

// Sin contenido reconocible
if (!messageText) {
  return [{ json: { valid: false, reason: 'unsupported_or_empty_message', remoteJid, msgKeys: Object.keys(msg) } }];
}

return [{ json: {
  valid: true,
  phone,
  remoteJid,
  pushName,
  messageText,
  messageType,
  messageId,
  instance,
  timestamp: new Date(timestamp * 1000).toISOString()
}}];

const msg = $('🔎 Extraer y Validar Mensaje').first().json;
return [{ json: {
  operation: 'getOrCreateUser',
  params: {
    phone:    msg.phone,
    name:     msg.pushName || null,
    language: 'es'
  }
}}];

const userId = $('🗄️ DB — Usuario').first().json.data[0].id;
return [{ json: {
  operation: 'getActiveSession',
  params: { userId }
}}];

// TRUE path: sesión activa encontrada en DB
const session  = $('🗄️ DB — Sesión Activa').first().json.data[0];
const userData = $('🗄️ DB — Usuario').first().json.data[0];
const msgData  = $('🔎 Extraer y Validar Mensaje').first().json;

return [{ json: {
  userId:         userData.id,
  userName:       userData.name || msgData.pushName || null,
  userLanguage:   userData.language || 'es',
  userPhone:      userData.phone,
  sessionId:      session.id,
  activeAgent:    session.active_agent,
  sessionState:   session.state,
  sessionContext: typeof session.context === 'string' ? JSON.parse(session.context || '{}') : (session.context || {}),
  isNewSession:   false,
  messageText:    msgData.messageText,
  messageType:    msgData.messageType,
  remoteJid:      msgData.remoteJid,
  instance:       msgData.instance
}}];

// FALSE path: no hay sesión, la creamos con NOVA como agente inicial
const userId = $('🗄️ DB — Usuario').first().json.data[0].id;
return [{ json: {
  operation: 'createSession',
  params: { userId, agent: 'NOVA', state: 'initial', context: {} }
}}];

// FALSE path: sesión recién creada
const session  = $('🗄️ DB — Crear Sesión').first().json.data[0];
const userData = $('🗄️ DB — Usuario').first().json.data[0];
const msgData  = $('🔎 Extraer y Validar Mensaje').first().json;

return [{ json: {
  userId:         userData.id,
  userName:       userData.name || msgData.pushName || null,
  userLanguage:   userData.language || 'es',
  userPhone:      userData.phone,
  sessionId:      session.id,
  activeAgent:    session.active_agent,
  sessionState:   session.state,
  sessionContext: {},
  isNewSession:   true,
  messageText:    msgData.messageText,
  messageType:    msgData.messageType,
  remoteJid:      msgData.remoteJid,
  instance:       msgData.instance
}}];

// Este nodo recibe data de CUALQUIERA de los dos Normalizar nodes.
// $json contiene el contexto unificado de la sesión.
const s = $json;

return [{ json: {
  operation: 'saveMessage',
  params: {
    userId:      s.userId,
    sessionId:   s.sessionId,
    agent:       s.activeAgent,
    role:        'user',
    message:     s.messageText,
    messageType: s.messageType
  },
  // Transportar contexto de sesión para nodos posteriores
  _session: {
    userId:         s.userId,
    userName:       s.userName,
    userLanguage:   s.userLanguage,
    userPhone:      s.userPhone,
    sessionId:      s.sessionId,
    activeAgent:    s.activeAgent,
    sessionState:   s.sessionState,
    sessionContext: s.sessionContext,
    isNewSession:   s.isNewSession,
    messageText:    s.messageText,
    messageType:    s.messageType,
    remoteJid:      s.remoteJid,
    instance:       s.instance
  }
}}];

// ============================================================
// INTENT ROUTER v1.0.0
// Determina qué agente debe manejar este mensaje.
// Lógica: sesión activa primero, luego detección por keywords.
// Cuando se integre Claude API, reemplazar keyword detection
// con llamada a Claude para detección de intención más precisa.
// ============================================================

// Recuperar contexto de la sesión (guardado en el payload anterior)
const session = $('📦 Payload — Guardar Mensaje Entrante').first().json._session;

const txt         = (session.messageText || '').toLowerCase().trim();
const msgType     = session.messageType;
const activeAgent = session.activeAgent;
const isNew       = session.isNewSession;

// ── REGLA 1: Respetar agente activo en sesiones en curso ─────
// Si el usuario ya está con SAGE o ATLAS, no interrumpir.
// Solo NOVA puede redirigir a otros agentes.
if (activeAgent === 'SAGE'  && !isNew) return [{ json: { ...session, targetAgent: 'SAGE',  intentDetected: 'continue_sage',  pendingHandoff: null } }];
if (activeAgent === 'ATLAS' && !isNew) return [{ json: { ...session, targetAgent: 'ATLAS', intentDetected: 'continue_atlas', pendingHandoff: null } }];

// ── REGLA 2: Botones interactivos ─────────────────────────────
// Detectar respuestas a botones/listas de mensajes previos.
if (msgType === 'button_reply') {
  if (txt.includes('cotizar') || txt === 'cotizar') return [{ json: { ...session, targetAgent: 'NOVA', intentDetected: 'cotizar_button',  pendingHandoff: 'SAGE'  } }];
  if (txt.includes('comparar') || txt === 'comparar') return [{ json: { ...session, targetAgent: 'NOVA', intentDetected: 'comparar_button', pendingHandoff: 'ATLAS' } }];
  if (txt.includes('agendar')  || txt === 'agendar')  return [{ json: { ...session, targetAgent: 'NOVA', intentDetected: 'agendar_button',  pendingHandoff: null   } }];
  // Botón no reconocido → NOVA maneja
  return [{ json: { ...session, targetAgent: 'NOVA', intentDetected: 'unknown_button', pendingHandoff: null } }];
}

// ── REGLA 3: Keywords de texto ─────────────────────────────────
// Listas de palabras clave por intención
const KW_COTIZAR = [
  'cotiz','precio','cuánto','cuanto','costo','tarifa',
  'implante','corona dental','carilla','veneer','ortodoncia','bracket','invisalign','alineador',
  'blanqueamiento','endodoncia','conducto','extraccion','extracción','puente dental',
  'rinoplastia','liposuccion','liposucción','abdominoplastia','mamario','aumento',
  'bichectomia','blefaroplastia','bbл','bbl','lifting','otoplastia',
  'procedimiento','cirugía','cirugia','dental','dentista','diente','muela'
];
const KW_COMPARAR = [
  'compar','destino','viajar','viaje','vuelo','hotel','turismo médico','turismo medico',
  'méxico','mexico','colombia','bogotá','bogota','medellín','medellin','cartagena',
  'perú','peru','lima','costa rica','argentina','buenos aires','dominicana','miami',
  'costo total','costo del viaje','cuánto me sale','hospedaje'
];
const KW_AGENDAR = [
  'agendar','cita','reservar','agenda','turno','appointment',
  'disponibilidad','horario','me atiendan','quiero ver','consulta'
];
const KW_SALUDO = [
  'hola','hi','hey','buenos días','buenas tardes','buenas noches',
  'buenas','hello','ola','start','inicio','empezar','comenzar','iniciar'
];

const hasCotizar  = KW_COTIZAR.some(kw  => txt.includes(kw));
const hasComparar = KW_COMPARAR.some(kw => txt.includes(kw));
const hasAgendar  = KW_AGENDAR.some(kw  => txt.includes(kw));
const hasSaludo   = KW_SALUDO.some(kw   => txt.includes(kw));

// Cotizar tiene prioridad sobre comparar
if (hasCotizar)  return [{ json: { ...session, targetAgent: 'NOVA', intentDetected: 'cotizar_keyword',  pendingHandoff: 'SAGE'  } }];
if (hasComparar) return [{ json: { ...session, targetAgent: 'NOVA', intentDetected: 'comparar_keyword', pendingHandoff: 'ATLAS' } }];
if (hasAgendar)  return [{ json: { ...session, targetAgent: 'NOVA', intentDetected: 'agendar_keyword',  pendingHandoff: null   } }];
if (hasSaludo)   return [{ json: { ...session, targetAgent: 'NOVA', intentDetected: 'saludo',           pendingHandoff: null   } }];

// Sin intención clara → NOVA orienta
return [{ json: { ...session, targetAgent: 'NOVA', intentDetected: 'unclear', pendingHandoff: null } }];

// ============================================================
// PREPARAR ENVÍO WHATSAPP v1.0.1
// Recibe output de NOVA, SAGE o ATLAS.
// Prepara payload para Evolution API V2.
// Fix: validación de sessionId + número siempre presente.
// ============================================================

const a = $json;

// Safeguard sessionId — NaN y undefined se convierten a null
// para que updateSession falle explícitamente en vez de silenciosamente.
const rawSessionId  = a.sessionId;
const safeSessionId = (rawSessionId !== null && rawSessionId !== undefined &&
                       Number.isInteger(Number(rawSessionId)) &&
                       Number(rawSessionId) > 0)
  ? Number(rawSessionId)
  : null;

if (!safeSessionId) {
  console.error(`[PANGI] ⚠️ sessionId inválido del agente: "${rawSessionId}". Agent: ${a.newActiveAgent}`);
}

// Safeguard remoteJid — sin esto Evolution API devuelve 400 Bad Request
const remoteJid = a.remoteJid || null;
if (!remoteJid) {
  console.error(`[PANGI] ⚠️ remoteJid ausente en output del agente: ${a.newActiveAgent}`);
}

const instanceName = a.instance || 'Test1';

return [{ json: {
  evolutionUrl:  `https://evolution.coopelmilagro.com/message/sendText/${instanceName}`,
  evolutionBody: JSON.stringify({
    number: remoteJid,
    text:   a.responseText || 'Error interno. Por favor escribe de nuevo.',
    delay:  1000
  }),
  _responseText:        a.responseText || '',
  _remoteJid:           remoteJid,
  _instance:            instanceName,
  _userId:              a.userId,
  _sessionId:           safeSessionId,
  _newActiveAgent:      a.newActiveAgent  || 'NOVA',
  _newSessionState:     a.newSessionState || 'active',
  _newSessionContext:   a.newSessionContext || {}
}}];

// Recuperar contexto del nodo de preparación (anterior al HTTP)
const prep = $('📤 Preparar Envío WhatsApp').first().json;

return [{ json: {
  operation: 'updateSession',
  params: {
    sessionId: prep._sessionId,
    agent:     prep._newActiveAgent,
    state:     prep._newSessionState,
    context:   prep._newSessionContext
  },
  // Transportar para guardar mensaje saliente
  _prep: prep
}}];

const prep = $('📦 Payload — Update Session').first().json._prep;

return [{ json: {
  operation: 'saveMessage',
  params: {
    userId:      prep._userId,
    sessionId:   prep._sessionId,
    agent:       prep._newActiveAgent,
    role:        'assistant',
    message:     prep._responseText,
    messageType: 'text'
  }
}}];

// Mensajes filtrados silenciosamente.
// Esto es intencional: no queremos responder a bots,
// grupos, estados, ni mensajes propios.
const reason = $json.reason || 'unknown';
console.log(`[PANGI] Mensaje ignorado. Razón: ${reason}`);
return [{ json: { ignored: true, reason } }];
